@@ -7 +6,0 @@ import java.io.IOException;
-import java.security.SecureRandom;
@@ -23 +22 @@ public class Header implements Cloneable {
-  private static final Random random = new SecureRandom();
+  private static final Random random = Utils.secureRandom();
diff --git a/src/main/java/org/xbill/DNS/NioUdpClient.java b/src/main/java/org/xbill/DNS/NioUdpClient.java
index bfd2da3e..4c31c90a 100644
--- a/src/main/java/org/xbill/DNS/NioUdpClient.java
+++ b/src/main/java/org/xbill/DNS/NioUdpClient.java
@@ -51 +51 @@ final class NioUdpClient extends NioClient implements UdpIoClient {
